import type { ProviderBStorage, Reservation, Service, ServiceResponse, Stock } from "./types";
import { error, parseReservationCommand, reservationResponse } from "./reservation";
import {
  decodeProviderBReservationRow,
  decodeProviderBStockRow,
  encodeCanonicalDecimal,
  encodeProviderBReservationRow,
  encodeProviderBStockRow,
  isRecord,
  isRevision,
} from "./validation";

type Lookup<T> =
  | { kind: "found"; value: T }
  | { kind: "missing" }
  | { kind: "unavailable" };

function missingOrUnavailable(envelope: unknown): "missing" | "unavailable" {
  if (!isRecord(envelope) || envelope.ok !== false || !isRecord(envelope.error)) return "unavailable";
  if (envelope.error.reason === "NO_SUCH_KEY") return "missing";
  return "unavailable";
}

async function readStock(storage: ProviderBStorage, sku: string): Promise<Lookup<Stock>> {
  try {
    const envelope = await storage.read({ collection: "inventory", key: sku });
    if (isRecord(envelope) && envelope.ok === true) {
      const stock = decodeProviderBStockRow(envelope.value);
      return stock !== undefined && stock.sku === sku
        ? { kind: "found", value: stock }
        : { kind: "unavailable" };
    }
    const outcome = missingOrUnavailable(envelope);
    return outcome === "missing" ? { kind: "missing" } : { kind: "unavailable" };
  } catch {
    return { kind: "unavailable" };
  }
}

async function readReservation(storage: ProviderBStorage, reservationId: string): Promise<Lookup<Reservation>> {
  try {
    const envelope = await storage.read({ collection: "reservations", key: reservationId });
    if (isRecord(envelope) && envelope.ok === true) {
      const reservation = decodeProviderBReservationRow(envelope.value);
      return reservation !== undefined && reservation.reservationId === reservationId
        ? { kind: "found", value: reservation }
        : { kind: "unavailable" };
    }
    const outcome = missingOrUnavailable(envelope);
    return outcome === "missing" ? { kind: "missing" } : { kind: "unavailable" };
  } catch {
    return { kind: "unavailable" };
  }
}

export function createProviderBReservationService({ storage }: { storage: ProviderBStorage }): Service {
  return {
    async handle(raw): Promise<ServiceResponse> {
      const command = parseReservationCommand(raw);
      if (command === undefined) return error(400, "invalid_command");

      if (command.op === "getAvailability") {
        const lookup = await readStock(storage, command.sku);
        if (lookup.kind === "missing") return error(404, "stock_not_found");
        if (lookup.kind === "unavailable") return error(500, "storage_unavailable");
        const stock = lookup.value;
        return {
          status: 200,
          body: {
            sku: stock.sku,
            totalUnits: stock.totalUnits,
            reservedUnits: stock.reservedUnits,
            availableUnits: stock.totalUnits - stock.reservedUnits,
          },
        };
      }

      const reservationLookup = await readReservation(storage, command.reservationId);
      if (reservationLookup.kind === "unavailable") return error(500, "storage_unavailable");
      if (command.op === "getReservation") {
        return reservationLookup.kind === "found"
          ? reservationResponse(200, reservationLookup.value)
          : error(404, "reservation_not_found");
      }

      if (reservationLookup.kind === "found") {
        const existing = reservationLookup.value;
        return existing.sku === command.sku && existing.quantity === command.quantity
          ? reservationResponse(200, existing)
          : error(409, "reservation_conflict");
      }

      const stockLookup = await readStock(storage, command.sku);
      if (stockLookup.kind === "missing") return error(404, "stock_not_found");
      if (stockLookup.kind === "unavailable") return error(500, "storage_unavailable");
      const stock = stockLookup.value;
      if (stock.totalUnits - stock.reservedUnits < command.quantity) {
        return error(409, "insufficient_stock");
      }
      const nextRevision = stock.revision + 1;
      if (!isRevision(nextRevision)) return error(500, "storage_unavailable");

      const reservation: Reservation = {
        reservationId: command.reservationId,
        sku: command.sku,
        quantity: command.quantity,
      };
      const nextStock: Stock = {
        ...stock,
        reservedUnits: stock.reservedUnits + command.quantity,
        revision: nextRevision,
      };
      try {
        const outcome = await storage.commitBatch({
          expectedRevisionText: encodeCanonicalDecimal(stock.revision),
          stockRow: encodeProviderBStockRow(nextStock),
          reservationRow: encodeProviderBReservationRow(reservation),
          outboxRows: [{
            key: "reservation.created:" + reservation.reservationId,
            category: "reservation",
            name: "created",
            payload: {
              bookingKey: reservation.reservationId,
              itemKey: reservation.sku,
              unitsText: encodeCanonicalDecimal(reservation.quantity),
            },
          }],
        });
        if (outcome === "revision_conflict") return error(409, "commit_conflict");
        if (outcome !== "applied") return error(500, "storage_unavailable");
        return reservationResponse(201, reservation);
      } catch {
        return error(500, "storage_unavailable");
      }
    },
  };
}

