import type { Service, ServiceResponse, StockReportSource } from "./types";
import { error } from "./reservation";
import { decodeStockSnapshotRow, isRecord, isUnits } from "./validation";

type LowStockCommand = {
  op: "lowStock";
  belowUnits: number;
};

type LowStockItem = {
  sku: string;
  availableUnits: number;
};

function parseCommand(raw: unknown): LowStockCommand | undefined {
  if (!isRecord(raw) || raw.op !== "lowStock" || !isUnits(raw.belowUnits)) return undefined;
  return { op: "lowStock", belowUnits: raw.belowUnits };
}

function isLowStockItem(value: LowStockItem | undefined): value is LowStockItem {
  return value !== undefined;
}

export function createStockReport({ source }: { source: StockReportSource }): Service {
  return {
    async handle(raw): Promise<ServiceResponse> {
      const command = parseCommand(raw);
      if (command === undefined) return error(400, "invalid_command");
      try {
        const snapshot = await source.readSnapshot();
        if (!Array.isArray(snapshot)) return error(500, "storage_unavailable");
        const seenSkus = new Set<string>();
        const items = snapshot
          .map((row) => decodeStockSnapshotRow(row))
          .map((row) => {
            if (row === undefined || seenSkus.has(row.sku)) return undefined;
            seenSkus.add(row.sku);
            return {
              sku: row.sku,
              availableUnits: row.totalUnits - row.reservedUnits,
            };
          });
        if (items.some((item) => item === undefined)) return error(500, "storage_unavailable");
        return {
          status: 200,
          body: {
            items: items
              .filter(isLowStockItem)
              .filter((item) => item.availableUnits < command.belowUnits)
              .sort((left, right) => left.sku < right.sku ? -1 : left.sku > right.sku ? 1 : 0),
          },
        };
      } catch {
        return error(500, "storage_unavailable");
      }
    },
  };
}

