import type { ProviderBReservationRow, ProviderBStockRow, Reservation, Stock, StockSnapshotRow } from "./types";

export function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

export function isId(value: unknown): value is string {
  return typeof value === "string" && value.length > 0;
}

export function isUnits(value: unknown): value is number {
  return typeof value === "number" && Number.isInteger(value) &&
    value >= 0 && value <= 1_000_000;
}

export function isQuantity(value: unknown): value is number {
  return isUnits(value) && value > 0;
}

export function isRevision(value: unknown): value is number {
  return typeof value === "number" && Number.isSafeInteger(value) && value >= 0;
}

export function decodeStock(value: unknown): Stock | undefined {
  if (!isRecord(value) || !isId(value.sku) || !isUnits(value.totalUnits) ||
      !isUnits(value.reservedUnits) || value.reservedUnits > value.totalUnits ||
      !isRevision(value.revision)) return undefined;
  return {
    sku: value.sku,
    totalUnits: value.totalUnits,
    reservedUnits: value.reservedUnits,
    revision: value.revision,
  };
}

export function decodeStockSnapshotRow(value: unknown): StockSnapshotRow | undefined {
  if (!isRecord(value) || !isId(value.sku) || !isUnits(value.totalUnits) ||
      !isUnits(value.reservedUnits) || value.reservedUnits > value.totalUnits) return undefined;
  return {
    sku: value.sku,
    totalUnits: value.totalUnits,
    reservedUnits: value.reservedUnits,
  };
}

export function decodeReservation(value: unknown): Reservation | undefined {
  if (!isRecord(value) || !isId(value.reservationId) ||
      !isId(value.sku) || !isQuantity(value.quantity)) return undefined;
  return {
    reservationId: value.reservationId,
    sku: value.sku,
    quantity: value.quantity,
  };
}

export function decodeCanonicalDecimal(value: unknown): number | undefined {
  if (typeof value !== "string" || !/^(0|[1-9][0-9]*)$/.test(value)) return undefined;
  const decoded = Number(value);
  return Number.isSafeInteger(decoded) ? decoded : undefined;
}

export function encodeCanonicalDecimal(value: number): string {
  return String(value);
}

export function decodeProviderBStockRow(value: unknown): Stock | undefined {
  if (!isRecord(value) || !isId(value.itemKey)) return undefined;
  const totalUnits = decodeCanonicalDecimal(value.onHandText);
  const reservedUnits = decodeCanonicalDecimal(value.heldText);
  const revision = decodeCanonicalDecimal(value.revisionText);
  if (totalUnits === undefined || reservedUnits === undefined || revision === undefined ||
      !isUnits(totalUnits) || !isUnits(reservedUnits) || reservedUnits > totalUnits ||
      !isRevision(revision)) return undefined;
  return {
    sku: value.itemKey,
    totalUnits,
    reservedUnits,
    revision,
  };
}

export function decodeProviderBReservationRow(value: unknown): Reservation | undefined {
  if (!isRecord(value) || !isId(value.bookingKey) || !isId(value.itemKey)) return undefined;
  const quantity = decodeCanonicalDecimal(value.unitsText);
  if (quantity === undefined || !isQuantity(quantity)) return undefined;
  return {
    reservationId: value.bookingKey,
    sku: value.itemKey,
    quantity,
  };
}

export function encodeProviderBStockRow(stock: Stock): ProviderBStockRow {
  return {
    itemKey: stock.sku,
    onHandText: encodeCanonicalDecimal(stock.totalUnits),
    heldText: encodeCanonicalDecimal(stock.reservedUnits),
    revisionText: encodeCanonicalDecimal(stock.revision),
  };
}

export function encodeProviderBReservationRow(reservation: Reservation): ProviderBReservationRow {
  return {
    bookingKey: reservation.reservationId,
    itemKey: reservation.sku,
    unitsText: encodeCanonicalDecimal(reservation.quantity),
  };
}
